INSERT INTO repo_cf_skills (cf_skill_id, education_level, sub_heading, text, status) VALUES ('CFS_SDG04_ADULT_003', 'Adult education', 'Critical reflection and social analysis', 'Analyse how poverty, gender norms and structural inequalities impact educational access in the community.', 'Active'), ('CFS_SDG04_ADULT_004', 'Adult education', 'Critical reflection and social analysis', 'Reflect on one’s own life experiences to identify educational gaps and potential pathways forward.', 'Active'), ('CFS_SDG04_ADULT_005', 'Adult education', 'Supportive parenting and family literacy', 'Design or participate in activities that promote children’s physical, intellectual, emotional and social development at home and in the community.', 'Active'), ('CFS_SDG04_ADULT_006', 'Adult education', 'Supportive parenting and family literacy', 'Apply parenting and caregiving knowledge to support early learning, school readiness and educational engagement at home.', 'Active'), ('CFS_SDG04_ADULT_007', 'Adult education', 'Community participation and lifelong learning', 'Engage in community initiatives that promote education, health and livelihoods.', 'Active'), ('CFS_SDG04_ADULT_008', 'Adult education', 'Community participation and lifelong learning', 'Collaborate with others in local planning or advocacy for improved educational services and support systems.', 'Active'), ('CFS_SDG05_SEC_001', 'Secondary education', 'Mitigating gender-based violence (GBV)', 'Develop and implement strategies to mitigate gender-based violence (GBV) through initiatives such as peer mediation, educational campaigns and community outreach programmes.', 'Active'), ('CFS_SDG05_SEC_002', 'Secondary education', 'Mitigating gender-based violence (GBV)', 'Critically assess national and international laws and policies aimed at protecting individuals from GBV and gender-based discrimination. Propose improvements based on gaps identified in these frameworks.', 'Active'), ('CFS_SDG05_SEC_003', 'Secondary education', 'Promoting gender equality', 'Design and lead awareness campaigns, school events or peer programmes that promote gender equality, challenge harmful gender stereotypes and encourage inclusivity.', 'Active'), ('CFS_SDG05_SEC_004', 'Secondary education', 'Promoting gender equality', 'Produce and distribute content (for example, videos, posters, blogs, social media) that challenges harmful gender stereotypes and promotes inclusive values, encouraging others to rethink societal norms.', 'Active'), ('CFS_SDG05_SEC_005', 'Secondary education', 'Promoting gender equality', 'Assess gender dynamics in schools and local communities, proposing inclusive solutions such as creating mixed-gender clubs, ensuring equal access to leadership roles and promoting gender-neutral policies.', 'Active'), ('CFS_SDG05_SEC_006', 'Secondary education', 'Implement intersectional strategies', 'Apply intersectional approaches in project design and leadership to ensure inclusivity, equitable representation and support for diverse gender identities, including race, class and ability.', 'Active'), ('CFS_SDG05_SEC_007', 'Secondary education', 'Collaboration and advocacy', 'Collaborate with peers, educators and community members to design and implement initiatives that promote equal opportunities in education and career pathways for all genders.', 'Active'), ('CFS_SDG05_SEC_008', 'Secondary education', 'Collaboration and advocacy', 'Study gender inequalities across global and cultural contexts, identifying discriminatory practices and proposing strategies to improve gender equity in various societies.', 'Active'), ('CFS_SDG05_SEC_009', 'Secondary education', 'Collaboration and advocacy', 'Develop counter-narratives versus a contemporary landscape marked by a resurgence of anti-feminist and misogynistic narratives, amplified through online platforms and social media influencers.', 'Active'), ('CFS_SDG05_SEC_010', 'Secondary education', 'Monitoring and adapting gender equality actions', 'Monitor and evaluate the impact of gender equality initiatives, adapting strategies based on ongoing reflection, feedback and lessons learned from each project or programme.', 'Active'), ('CFS_SDG05_SEC_011', 'Secondary education', 'Monitoring and adapting gender equality actions', 'Lead or participate in school or community projects addressing gender inequality and advocate for positive change.', 'Active'), ('CFS_SDG05_SEC_012', 'Secondary education', 'Leadership, empowerment and responsibility', 'Lead and participate in gender equality initiatives, such as mixed-gender clubs or student councils that promote equal representation and participation.', 'Active'), ('CFS_SDG05_SEC_013', 'Secondary education', 'Leadership, empowerment and responsibility', 'Promote and model gender-sensitive leadership, decision-making and conflict resolution.', 'Active'), ('CFS_SDG05_SEC_014', 'Secondary education', 'Leadership, empowerment and responsibility', 'Propose and implement school-wide or community-based solutions, such as equal access to leadership roles, fair classroom responsibilities, or equitable participation in sports and STEM.', 'Active'), ('CFS_SDG05_SEC_015', 'Secondary education', 'Leadership, empowerment and responsibility', 'Monitor the effectiveness of gender equality projects and use feedback to improve future actions, promoting a cycle of reflection, learning and action.', 'Active'), ('CFS_SDG05_TVET_001', 'TVET', 'Promoting gender equality in TVET', 'Identify and address gender disparities in TVET programmes and design targeted strategies to increase the participation of under-represented groups, particularly women and gender minorities, in technical education and training.', 'Active'), ('CFS_SDG05_TVET_002', 'TVET', 'Promoting gender equality in TVET', 'Use inclusive curriculum development and teaching methods that cater to the needs of all genders, ensuring that the learning environment is accessible, non-discriminatory and promotes equal opportunities for all students.', 'Active'), ('CFS_SDG05_TVET_003', 'TVET', 'Promoting gender equality in TVET', 'Integrate gender considerations into TVET programme planning, budgeting and resource allocation, ensuring that gender equality is embedded into the design and implementation of training programmes.', 'Active'), ('CFS_SDG05_TVET_004', 'TVET', 'Data analysis and evaluation', 'Use data analysis to identify gender gaps in participation, progression and employment outcomes in TVET programmes. Evaluate the effectiveness of gender equality interventions and make data-driven recommendations for improvement.', 'Active'), ('CFS_SDG05_TVET_005', 'TVET', 'Data analysis and evaluation', 'Monitor and evaluate the impact of gender-inclusive policies and initiatives in TVET institutions and workplaces, using metrics to assess progress and inform decision-making processes.', 'Active'), ('CFS_SDG05_TVET_006', 'TVET', 'Awareness and advocacy', 'Design and implement awareness campaigns, mentorship networks and school-based initiatives that promote gender equality in technical education, encouraging all students to pursue diverse career paths.', 'Active'), ('CFS_SDG05_TVET_007', 'TVET', 'Awareness and advocacy', 'Provide gender-sensitive career guidance to challenge existing stereotypes and broaden vocational aspirations, ensuring that both male and female students feel empowered to pursue careers in diverse technical fields.', 'Active'), ('CFS_SDG05_TVET_008', 'TVET', 'Targeted interventions and support', 'Identify and address systemic barriers that hinder women’s participation in STEM and leadership roles within technical fields. Develop and implement targeted interventions, such as mentorship programmes, skills training and leadership development opportunities.', 'Active'), ('CFS_SDG05_TVET_009', 'TVET', 'Targeted interventions and support', 'Train and support women in entrepreneurship, ICT and business management, equipping them with the skills and knowledge to increase their economic participation and lead in tech-driven industries.', 'Active'), ('CFS_SDG05_TVET_010', 'TVET', 'Leveraging digital tools', 'Leverage digital tools and online learning platforms to enhance access to education and bridge gender gaps in technology-driven industries, ensuring that women and gender minorities have equal opportunities to gain skills in emerging fields like ICT and digital services.', 'Active'), ('CFS_SDG05_TVET_011', 'TVET', 'Creating inclusive environments', 'Propose solutions to create inclusive and respectful environments in TVET institutions and workplaces that respect diverse gender identities, promote safety, flexibility and equality, and accommodate the diverse needs of learners and workers.', 'Active'), ('CFS_SDG05_TER_001', 'Tertiary education', 'Gender-responsive education and advocacy', 'Facilitate inclusive sexual and reproductive health (SRH) education programmes tailored to adults, particularly in underserved and rural areas.', 'Active'), ('CFS_SDG05_TER_002', 'Tertiary education', 'Gender-responsive education and advocacy', 'Design and advocate for gender-neutral curricula and teaching practices that promote equality in learning environments.', 'Active'), ('CFS_SDG05_TER_003', 'Tertiary education', 'Gender-responsive education and advocacy', 'Provide equal attention and opportunities to both boys and girls in educational settings for an inclusive and balanced approach.', 'Active'), ('CFS_SDG05_TER_004', 'Tertiary education', 'Gender-responsive education and advocacy', 'Apply participatory tools, such as the 24-hour time chart, to spark dialogue on redistributing unpaid care and domestic work and its impact on gender equality.', 'Active'), ('CFS_SDG05_TER_005', 'Tertiary education', 'Gender-responsive education and advocacy', 'Design interventions aimed at increasing women’s equitable access to land, water and economic resources, considering gender dynamics.', 'Active'), ('CFS_SDG05_TER_006', 'Tertiary education', 'Gender-responsive education and advocacy', 'Develop and implement strategies to prevent and respond to gender-based violence within educational and community settings.', 'Active'), ('CFS_SDG05_TER_007', 'Tertiary education', 'Gender-responsive education and advocacy', 'Educate communities on harmful practices affecting women’s health and rights and mobilise efforts for legal and cultural change.', 'Active'), ('CFS_SDG05_TER_008', 'Tertiary education', 'Gender-responsive education and advocacy', 'Create mentorship programmes that support girls in overcoming barriers to education and career opportunities, especially in male-dominated fields.', 'Active'), ('CFS_SDG05_TER_009', 'Tertiary education', 'Community engagement and empowerment', 'Work with governments, NGOs and community groups to drive systemic change in education and tackle the root causes of gender inequality.', 'Active'), ('CFS_SDG05_TER_010', 'Tertiary education', 'Community engagement and empowerment', 'Review international, national and local policies to ensure equal access to sexual and reproductive health services and informed decision-making rights.', 'Active'), ('CFS_SDG05_TER_011', 'Tertiary education', 'Community engagement and empowerment', 'Promote inclusive leadership and engage men and boys in challenging patriarchal norms and supporting gender equality.', 'Active'), ('CFS_SDG05_TER_012', 'Tertiary education', 'Community engagement and empowerment', 'Empower women in sustainable agriculture, climate adaptation, and natural resource management through gender-responsive environmental strategies.', 'Active'), ('CFS_SDG05_TER_013', 'Tertiary education', 'Leadership and gender equality in institutions', 'Promote gender-sensitive leadership within educational institutions to support gender equality across all levels of administration and teaching.', 'Active'), ('CFS_SDG05_TER_014', 'Tertiary education', 'Leadership and gender equality in institutions', 'Provide leadership training for women to increase their participation in decision-making spaces.', 'Active'), ('CFS_SDG05_TER_015', 'Tertiary education', 'Leadership and gender equality in institutions', 'Encourage peer education models that involve men and boys in promoting gender equity and transforming masculinities.', 'Active'), ('CFS_SDG05_TER_016', 'Tertiary education', 'Leadership and gender equality in institutions', 'Advocate for systemic change through grassroots campaigns, digital media advocacy and policy lobbying, mobilising community action around gender equality.', 'Active'), ('CFS_SDG05_TER_017', 'Tertiary education', 'Leadership and gender equality in institutions', 'Support the design and implementation of inclusive policies that address gender disparities in educational systems and ensure equal access to resources and opportunities.', 'Active'), ('CFS_SDG05_TER_018', 'Tertiary education', 'Leadership and gender equality in institutions', 'Recognise the importance of creating and implementing strategies that encourage gender equality through education, lifelong learning and leadership.', 'Active') ON CONFLICT DO NOTHING;